export default function runFade(ctx) {
  if (ctx.reversed) {
    return {
      reverseStack: true,
      animations: [{
        pseudoElement: '::view-transition-old(root)',
        keyframes: [{
          opacity: 1
        }, {
          opacity: 0
        }]
      }]
    };
  }
  return {
    animations: [{
      pseudoElement: '::view-transition-new(root)',
      keyframes: [{
        opacity: 0
      }, {
        opacity: 1
      }]
    }]
  };
}
flarum.reg.add('huseyinfiliz-theme-transitions', 'common/transitions/effects/fade', runFade);